.version 8.0
.target sm_89
.address_size 64
.visible .entry matmul_tiled(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    .reg .pred pA, pB, pRowIn, pColIn, pKAIn, pKBIn, pLoopEnd, pStore, pSingle;
    .reg .f32 acc, a, b, z;
    .reg .u32 rM, rN, rK, rBx, rBy, rBz, rGz, rTx, rTy, rRow, rCol, rKbase, rKidxA, rKidxB, rk, idx32, rKslice, rKstart, rKend, tmp32;
    .reg .u64 A, B, C, gA, gB, gC, off64, baseSA, baseSB, offA, offB, idx64, tmp64;
    .shared .align 4 .b8 sA[1024];
    .shared .align 4 .b8 sB[1024];
    // Load parameters
    ld.param.u64 A, [A_ptr];
    ld.param.u64 B, [B_ptr];
    ld.param.u64 C, [C_ptr];
    ld.param.u32 rM, [M];
    ld.param.u32 rN, [N];
    ld.param.u32 rK, [K];
    // Convert to global addresses
    cvta.to.global.u64 gA, A;
    cvta.to.global.u64 gB, B;
    cvta.to.global.u64 gC, C;
    // Thread and block indices
    mov.u32 rTx, %tid.x;
    mov.u32 rTy, %tid.y;
    mov.u32 rBx, %ctaid.x;
    mov.u32 rBy, %ctaid.y;
    mov.u32 rBz, %ctaid.z;
    mov.u32 rGz, %nctaid.z;
    // Compute output row and column
    mad.lo.u32 rRow, rBy, 16, rTy;
    mad.lo.u32 rCol, rBx, 16, rTx;
    // Predicates for bounds
    setp.lt.u32 pRowIn, rRow, rM;
    setp.lt.u32 pColIn, rCol, rN;
    // Shared memory base pointers
    mov.u64 baseSA, sA;
    mov.u64 baseSB, sB;
    // Initialize accumulator
    mov.f32 acc, 0f00000000;
    mov.f32 z, 0f00000000;
    // Compute Split-K slice [rKstart, rKend)
    add.u32 tmp32, rK, rGz;
    sub.u32 tmp32, tmp32, 1;
    div.u32 rKslice, tmp32, rGz;       // ceil_div(rK, rGz)
    mul.lo.u32 rKstart, rBz, rKslice;  // start = bz * slice
    add.u32 rKend, rKstart, rKslice;   // end = start + slice
    setp.gt.u32 pLoopEnd, rKend, rK;
    @pLoopEnd mov.u32 rKend, rK;       // clamp to K
    mov.u32 rKbase, rKstart;
LoopK:
    setp.ge.u32 pLoopEnd, rKbase, rKend;
    @pLoopEnd bra EndK;
    // Indices along K for this tile
    add.u32 rKidxA, rKbase, rTx; // A load uses thread x as k-offset
    add.u32 rKidxB, rKbase, rTy; // B load uses thread y as k-offset
    // Load A[row, kIdxA] if in bounds, else 0
    mul.wide.u32 idx64, rRow, rK;   // row * K
    cvt.u64.u32 tmp64, rKidxA;
    add.u64 idx64, idx64, tmp64;    // row*K + kIdxA
    shl.b64 off64, idx64, 2;        // *4 bytes
    add.u64 off64, gA, off64;
    setp.lt.u32 pKAIn, rKidxA, rKend;  // bound to slice end
    and.pred pA, pRowIn, pKAIn;
    @pA ld.global.f32 a, [off64];
    @!pA mov.f32 a, z;
    // Load B[kIdxB, col] if in bounds, else 0
    mul.wide.u32 idx64, rKidxB, rN; // kIdxB * N
    cvt.u64.u32 tmp64, rCol;
    add.u64 idx64, idx64, tmp64;    // kIdxB*N + col
    shl.b64 off64, idx64, 2;        // *4 bytes
    add.u64 off64, gB, off64;
    setp.lt.u32 pKBIn, rKidxB, rKend;  // bound to slice end
    and.pred pB, pColIn, pKBIn;
    @pB ld.global.f32 b, [off64];
    @!pB mov.f32 b, z;
    // Store into shared tiles
    mad.lo.u32 idx32, rTy, 16, rTx;  // idx = ty*16 + tx
    mul.wide.u32 offA, idx32, 4;
    add.u64 offA, baseSA, offA;
    st.shared.f32 [offA], a;
    mul.wide.u32 offB, idx32, 4;
    add.u64 offB, baseSB, offB;
    st.shared.f32 [offB], b;
    // Synchronize before compute
    bar.sync 0;
    // Compute accumulation over the tile
    mov.u32 rk, 0;
KInner:
    setp.ge.u32 pLoopEnd, rk, 16;
    @pLoopEnd bra KDone;
    // a = sA[ty*16 + rk]
    mad.lo.u32 idx32, rTy, 16, rk;
    mul.wide.u32 offA, idx32, 4;
    add.u64 offA, baseSA, offA;
    ld.shared.f32 a, [offA];
    // b = sB[rk*16 + tx]
    mad.lo.u32 idx32, rk, 16, rTx;
    mul.wide.u32 offB, idx32, 4;
    add.u64 offB, baseSB, offB;
    ld.shared.f32 b, [offB];
    fma.rn.f32 acc, a, b, acc;
    add.u32 rk, rk, 1;
    bra KInner;
KDone:
    // Synchronize before next tile load
    bar.sync 0;
    // Advance K base
    add.u32 rKbase, rKbase, 16;
    bra LoopK;
EndK:
    // Store C[row, col] if within bounds
    and.pred pStore, pRowIn, pColIn;
    @!pStore bra StoreDone;
    mul.wide.u32 idx64, rRow, rN;  // row * N
    cvt.u64.u32 tmp64, rCol;
    add.u64 idx64, idx64, tmp64;   // row*N + col
    shl.b64 off64, idx64, 2;       // *4 bytes
    add.u64 off64, gC, off64;
    // Use atomicAdd for Split-K, plain store if no split (gridDim.z == 1)
    setp.eq.u32 pSingle, rGz, 1;
    @pSingle st.global.f32 [off64], acc;
    @!pSingle atom.global.add.f32 a, [off64], acc;
StoreDone:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_tiled")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        M = int(A.shape[0])
        K = int(A.shape[1])
        N = int(B.shape[1])

        module = _get_ptx_module()

        block_x = 16
        block_y = 16
        grid_x = (N + block_x - 1) // block_x
        grid_y = (M + block_y - 1) // block_y
        split_k = min(32, max(1, (K + 4095) // 4096))
        if split_k > 1:
            C = torch.zeros((M, N), device=A.device, dtype=A.dtype)
        else:
            C = torch.empty((M, N), device=A.device, dtype=A.dtype)
        module.launch(
            "matmul_tiled",
            grid=(grid_x, grid_y, split_k),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, i32(M), i32(N), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C
